import type { ComponentType } from 'react'
import type { ClientLoaderFunctionArgs, LoaderFunctionArgs, ShouldRevalidateFunction } from 'react-router'

/** A route of the manifest generated by `@cormi/preset-react` (`src/.cormi/routes.ts`). */
export interface RouteData {
  id: string
  path?: string
  index?: boolean
  parentId?: string
  /** the route module exports `loader`, which runs on the server */
  hasLoader?: boolean
  /** the route module exports `clientLoader`, which runs in the browser */
  hasClientLoader?: boolean
}

/** Exports of a route module. */
export interface RouteModule {
  default?: ComponentType
  /** runs on the server; removed from the client bundle */
  loader?: (args: LoaderFunctionArgs) => unknown
  /** runs in the browser */
  clientLoader?: (args: ClientLoaderFunctionArgs) => unknown
  ErrorBoundary?: ComponentType
  HydrateFallback?: ComponentType
  handle?: unknown
  shouldRevalidate?: ShouldRevalidateFunction
}

export type RouteModules = Record<string, () => Promise<RouteModule>>

declare global {
  interface Window {
    /** hydration data written by `StaticRouterProvider` during server rendering */
    __staticRouterHydrationData?: any
  }
}
